    uint64_t generation=capture->generation;CanvasMode mode=capture->mode;bool append=capture->append,comparison=capture->comparison,fitValidation=capture->fitValidation;std::string actionId=std::move(capture->actionId),previous=std::move(capture->previousResponseId);if(!error.empty()){if(!capture->apiKey.empty())SecureZeroMemory(capture->apiKey.data(),capture->apiKey.size());delete capture;if(fitValidation)QueueFitQualityResult({std::move(error),{},false});else QueueCanvasResult({std::move(error),{},false},generation,mode,append,std::move(actionId));return;}if(!fitValidation&&(generation!=canvasConversationGeneration||descriptionUserClosed)){if(!capture->apiKey.empty())SecureZeroMemory(capture->apiKey.data(),capture->apiKey.size());delete capture;requestRunning=false;return;}std::string key=std::move(capture->apiKey);uint32_t width=capture->width,height=capture->height;int format=capture->format;delete capture;if(fitValidation){openAIThread=std::thread([pixels=std::move(pixels),width,height,format,key=std::move(key)]() mutable {QueueFitQualityResult(CallOpenAIImage(pixels,width,height,format,CanvasMode::FitQuality,{},false,std::move(key)));});return;}openAIThread=std::thread([pixels=std::move(pixels),width,height,format,mode,previous=std::move(previous),comparison,key=std::move(key),generation,append,actionId=std::move(actionId)]() mutable {QueueCanvasResult(CallOpenAIImage(pixels,width,height,format,mode,previous,comparison,std::move(key)),generation,mode,append,std::move(actionId));});
